import Foundation

func fetchWithRetry(_ url: URL, attempts: Int = 3) async throws -> Data {
    var lastError: Error?
    for attempt in 1...attempts {
        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            return data
        } catch {
            lastError = error
            try await Task.sleep(nanoseconds: UInt64(attempt) * 500_000_000)
        }
    }
    throw lastError!
}

